**Gates before launch.** I run four gates in order. If any gate fails, I halt and report. First, I check that spe/predictions/r04.yaml and spe/plans/r04.md are committed and have not changed since that commit. Second, I run the selftest on spe/evals/graders/grade.py. The oracle is answers.json fed back in as the result, and it must pass all 50 tickets. An empty label must fail, and so must a shifted wrong label. The selftest also checks that answers.json has exactly 50 entries and that they match args.tickets, because the earlier set had 40. Third, I regrade round 3's saved results with this round's grade.py as a control. If any number differs from round 3, the grader changed, not the agent. I log that change in spe/failures.md before the run. Fourth, I dry run the script with args.only set to ["B:T001","C2:T002"] and args.trials set to 2. Every phase must return schema-valid output, the leak scan must run, and the ledger must show the real cost per trial. If that cost is so far above the $0.05 estimate that 500 trials plus the judge cannot fit under $40, I stop and ask you. After the gates pass, I commit spe/evals/harness/r04-workflow.js locally and launch the full run.

```js
// spe/evals/harness/r04-workflow.js
// Copied from r03-workflow.js and changed to match the approved plan in spe/plans/r04.md.
// Defaults I chose where the plan is silent:
//   A cell is one config on one ticket. One harness agent runs all trials of a cell.
//   The runner is the r03 runner: RUNNER --config X --ticket Y --trial K --out DIR. It prints JSON
//     (label, reply, cost_usd, runtime_s, tool_calls, tool_errors, input_tokens, output_tokens) and
//     writes DIR/result.json and DIR/transcript.jsonl.
//   grade.py is called as GRADER --run DIR/result.json and prints JSON with category_ok and priority_ok.
//   Run output goes under spe/runs/rNN, so trial reads never touch spe/evals/.
//   The $40 cap covers the runner's measured cost_usd plus estimates for grade, judge, and synthesis
//     agents. MAX_AGENTS caps the harness agents by count.

export const meta = {
  name: 'triage-spe-eval',
  description: 'Triage agent eval: configs B and C2 on the ticket set, code grader for labels, Opus judge for reply tone, spend cap, top-up of split cells, failure analysis, completeness critic.',
  phases: [
    { title: 'Trials' },
    { title: 'Grade' },
    { title: 'Top-up' },
    { title: 'Judge' },
    { title: 'Synthesis' },
  ],
}

// ---------- Round and arguments ----------
const ROUND = Number(args.round ?? 4)
const RR = String(ROUND).padStart(2, '0')

const CONFIGS = args.configs ?? ['B', 'C2']
const TICKETS = args.tickets ?? Array.from({ length: 50 }, (_, i) => `T${String(i + 1).padStart(3, '0')}`)
const EXPECT_TICKETS = Number(args.expectTickets ?? 50)
const TRIALS = Number(args.trials ?? 5)
const ONLY = args.only ?? null
const DRY = Boolean(ONLY)

const RUNNER = args.runner ?? 'node spe/evals/harness/run-triage.js'
const OUT = args.outDir ?? `spe/runs/r${RR}`
const GRADER = 'python spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json'
const JUDGE_RUBRIC = 'spe/evals/graders/judge.md'
const TICKET_PATH = args.ticketPath ?? 'spe/evals/tasks/tickets/{id}.json'
const WRAPPER_MODEL = args.wrapperModel ?? 'opus'

const SPEND_CAP = Number(args.spendCapUsd ?? 40)
const EST_TRIAL = Number(args.estTrialUsd ?? 0.05)
const EST_GRADE = Number(args.estGradeUsd ?? 0.10)
const EST_JUDGE = Number(args.estJudgeUsd ?? 0.15)
const MAX_AGENTS = Number(args.maxAgents ?? 250)
const TOPUP_PER_CELL = Number(args.topupPerCell ?? 5)
const TOPUP_CELL_CAP = Number(args.topupCellCap ?? 20)
const GRADE_BATCH = Number(args.gradeBatch ?? 25)
const SEED = Number(args.seed ?? ROUND * 1009)
const FA_MAX_ROWS = 150

const LEAK_PATTERN = 'spe/evals/graders|spe/evals/tasks/answers|spe/predictions/|spe/plans/|spe/prediction-log'

// ---------- Cells ----------
if (!DRY && TICKETS.length !== EXPECT_TICKETS) {
  throw new Error(`Expected ${EXPECT_TICKETS} tickets, got ${TICKETS.length}`)
}
const allCells = CONFIGS.flatMap(config => TICKETS.map(ticket => ({ config, ticket, id: `${config}:${ticket}` })))
const cells = DRY ? allCells.filter(c => ONLY.includes(c.id)) : allCells
if (cells.length === 0) throw new Error('No cells selected')
const judgeTickets = [...new Set(cells.map(c => c.ticket))]

// ---------- Budget ledger ----------
const gradeBatchesPlanned = Math.ceil((cells.length * TRIALS) / GRADE_BATCH)
const gradeBatchesTopup = Math.ceil((TOPUP_CELL_CAP * TOPUP_PER_CELL) / GRADE_BATCH)
const HOLD_BACK = EST_GRADE * (gradeBatchesPlanned + gradeBatchesTopup) + EST_JUDGE * (judgeTickets.length + 2)
const TRIAL_BUDGET = SPEND_CAP - HOLD_BACK

const ledger = { spent: 0, reserved: 0, trialSpent: 0, trialReserved: 0, agents: 0, skipped: [] }
const halt = []
let budgetHit = false

function addHalt(reason) {
  if (!halt.includes(reason)) {
    halt.push(reason)
    log(`HALT: ${reason}`)
  }
}

function capSkip(what, reason) {
  ledger.skipped.push({ what, reason })
  log(`SKIP ${what}: ${reason}`)
}

function reserveAgent(usd, what) {
  if (ledger.agents + 1 > MAX_AGENTS) {
    capSkip(what, `agent cap ${MAX_AGENTS}`)
    return false
  }
  if (ledger.spent + ledger.reserved + usd > SPEND_CAP) {
    capSkip(what, `spend cap $${SPEND_CAP}`)
    budgetHit = true
    return false
  }
  ledger.agents += 1
  ledger.reserved += usd
  return true
}

function settle(usd, actual) {
  ledger.reserved -= usd
  ledger.spent += Number.isFinite(actual) ? actual : usd
}

function reserveTrials(cell, nums, isTopup) {
  if (ledger.agents + 1 > MAX_AGENTS) {
    for (const k of nums) capSkip(`${cell.id}#${k}`, `agent cap ${MAX_AGENTS}`)
    return null
  }
  const trialRoom = TRIAL_BUDGET - ledger.trialSpent - ledger.trialReserved
  const totalRoom = SPEND_CAP - ledger.spent - ledger.reserved
  const fit = Math.max(0, Math.min(nums.length, Math.floor(Math.min(trialRoom, totalRoom) / EST_TRIAL)))
  const run = nums.slice(0, fit)
  for (const k of nums.slice(fit)) capSkip(`${cell.id}#${k}`, `spend cap $${SPEND_CAP}`)
  if (fit < nums.length && !isTopup) budgetHit = true
  if (run.length === 0) return null
  const usd = run.length * EST_TRIAL
  ledger.agents += 1
  ledger.reserved += usd
  ledger.trialReserved += usd
  return { run, usd }
}

function settleTrials(usd, actual) {
  const a = Number.isFinite(actual) ? actual : usd
  ledger.reserved -= usd
  ledger.trialReserved -= usd
  ledger.spent += a
  ledger.trialSpent += a
}

// ---------- Helpers ----------
function chunk(xs, n) {
  const out = []
  for (let i = 0; i < xs.length; i += n) out.push(xs.slice(i, i + n))
  return out
}

function groupBy(xs, f) {
  const m = {}
  for (const x of xs) {
    const k = f(x)
    if (!m[k]) m[k] = []
    m[k].push(x)
  }
  return m
}

function mean(xs) {
  return xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null
}

function rate(xs, f) {
  return xs.length ? xs.filter(f).length / xs.length : null
}

function rng(seed) {
  let a = seed >>> 0
  return function () {
    a = (a + 0x6D2B79F5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function shuffle(xs, rand) {
  const a = xs.slice()
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1))
    const tmp = a[i]
    a[i] = a[j]
    a[j] = tmp
  }
  return a
}

// ---------- Schemas ----------
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['trials'],
  properties: {
    trials: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial', 'status', 'label', 'reply', 'cost_usd', 'runtime_s', 'tool_calls', 'tool_errors', 'input_tokens', 'output_tokens'],
        properties: {
          trial: { type: 'integer' },
          status: { enum: ['ok', 'harness_error', 'rate_limited'] },
          label: {
            type: 'object',
            required: ['category', 'priority'],
            properties: {
              category: { type: ['string', 'null'] },
              priority: { type: ['string', 'null'] },
            },
          },
          reply: { type: ['string', 'null'] },
          cost_usd: { type: 'number' },
          runtime_s: { type: 'number' },
          tool_calls: { type: 'integer' },
          tool_errors: { type: 'integer' },
          input_tokens: { type: 'integer' },
          output_tokens: { type: 'integer' },
          error: { type: ['string', 'null'] },
        },
      },
    },
  },
}

const GRADE_SCHEMA = {
  type: 'object',
  required: ['results'],
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['key', 'grader_ran', 'category_ok', 'priority_ok', 'file_category', 'file_priority', 'peeked', 'peek_evidence'],
        properties: {
          key: { type: 'string' },
          grader_ran: { type: 'boolean' },
          grader_error: { type: ['string', 'null'] },
          category_ok: { type: ['boolean', 'null'] },
          priority_ok: { type: ['boolean', 'null'] },
          file_category: { type: ['string', 'null'] },
          file_priority: { type: ['string', 'null'] },
          peeked: { type: 'boolean' },
          peek_evidence: { type: 'string' },
        },
      },
    },
  },
}

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['rid', 'tone_score', 'tone_pass', 'reason'],
        properties: {
          rid: { type: 'string' },
          tone_score: { type: 'number' },
          tone_pass: { type: 'boolean' },
          reason: { type: 'string' },
        },
      },
    },
  },
}

const FA_SCHEMA = {
  type: 'object',
  required: ['types', 'suspected_grader_or_key_errors'],
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'kind', 'existing_f', 'counts', 'examples', 'how_to_spot', 'fix'],
        properties: {
          name: { type: 'string' },
          kind: { enum: ['category', 'priority', 'tone', 'tool use', 'harness'] },
          existing_f: { type: ['string', 'null'] },
          counts: { type: 'array', items: { type: 'object', required: ['config', 'count'], properties: { config: { type: 'string' }, count: { type: 'integer' } } } },
          examples: { type: 'array', items: { type: 'string' } },
          how_to_spot: { type: 'string' },
          fix: { type: 'string' },
        },
      },
    },
    suspected_grader_or_key_errors: { type: 'array', items: { type: 'object', required: ['key', 'why'], properties: { key: { type: 'string' }, why: { type: 'string' } } } },
  },
}

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['verdict', 'issues'],
  properties: {
    verdict: { enum: ['complete', 'gaps'] },
    issues: {
      type: 'array',
      items: {
        type: 'object',
        required: ['severity', 'issue', 'evidence'],
        properties: {
          severity: { enum: ['blocker', 'major', 'minor'] },
          issue: { type: 'string' },
          evidence: { type: 'string' },
        },
      },
    },
  },
}

// ---------- Prompts ----------
function trialPrompt(cell, nums, dir) {
  return [
    'You are a harness operator for the triage agent eval. You are not the agent under test. Your job is to run a command and copy its output.',
    '',
    `Config: ${cell.config}`,
    `Ticket id: ${cell.ticket}`,
    `Trial numbers: ${nums.join(', ')}`,
    '',
    'For each trial number K, run this command once from the repository root:',
    `  ${RUNNER} --config ${cell.config} --ticket ${cell.ticket} --trial K --out ${dir}/K`,
    'The command prints one JSON object on stdout. Copy its fields into your result for trial K. Do not change any value.',
    '',
    `You may read only the command output and files under ${dir}/.`,
    'Do not open, list, search, or print anything under spe/evals/graders/, spe/evals/tasks/, spe/predictions/, spe/plans/, spe/spec/, spe/prediction-log.md, or spe/failures.md.',
    'Do not decide whether a label is correct. Do not rerun a trial because you dislike its answer.',
    '',
    'If the command exits with an error, set status to harness_error. If it reports a rate limit, set status to rate_limited.',
    'In either case, wait 30 seconds, retry that trial once, and report the second attempt. Never write a label the command did not print.',
  ].join('\n')
}

function gradePrompt(batch) {
  const lines = batch.map(r => `${r.key}\t${r.dir}`).join('\n')
  return [
    'You grade triage trials with code. Do not grade anything by reading the reply yourself.',
    '',
    'Each line below gives a key and a run directory. For each line, do two things.',
    `1. Run: ${GRADER} --run <dir>/result.json`,
    '   Copy category_ok and priority_ok from its JSON output.',
    '   Copy label.category and label.priority from <dir>/result.json into file_category and file_priority.',
    '   If the grader exits with an error or prints no JSON, set grader_ran to false and copy the error text into grader_error. Do not grade by hand.',
    `2. Leak scan: in <dir>/transcript.jsonl, look only at tool call inputs. Set peeked to true if any input matches this regular expression: ${LEAK_PATTERN}`,
    '   Put the matching tool call in peek_evidence. Otherwise set peeked to false and peek_evidence to an empty string.',
    '',
    'Return one result per key.',
    '',
    lines,
  ].join('\n')
}

function judgePrompt(ticket, items) {
  const body = items.map(it => `### ${it.rid}\n${it.reply}`).join('\n\n')
  return [
    `You judge the tone of draft support replies. Read the rubric at ${JUDGE_RUBRIC} and apply its scale and pass line exactly.`,
    `Read the ticket at ${TICKET_PATH.replace('{id}', ticket)} so you know what the customer wrote.`,
    'Each reply below has an anonymous id. Score each reply on its own against the rubric. Do not rank the replies against each other.',
    'Score tone only. Do not score whether the category or priority is right.',
    `Do not open spe/predictions/, spe/plans/, or anything under ${OUT}/.`,
    '',
    body,
  ].join('\n')
}

// ---------- Trial runner ----------
async function runCell(cell, nums, phaseName) {
  const isTopup = phaseName === 'Top-up'
  const res = reserveTrials(cell, nums, isTopup)
  if (!res) return []
  const { run, usd } = res
  const dir = `${OUT}/${cell.config}/${cell.ticket}`
  let out
  try {
    out = await agent(trialPrompt(cell, run, dir), {
      label: `${isTopup ? 'top-up' : 'trial'} ${cell.id} #${run.join(',')}`,
      phase: phaseName,
      schema: TRIAL_SCHEMA,
      model: WRAPPER_MODEL,
    })
  } catch (e) {
    settleTrials(usd, usd)
    log(`Harness error on ${cell.id}: ${String(e)}`)
    return run.map(k => ({ config: cell.config, ticket: cell.ticket, cell: cell.id, trial: k, key: `${cell.id}#${k}`, dir: `${dir}/${k}`, topup: isTopup, status: 'harness_error', error: String(e) }))
  }
  const rows = (out.trials ?? []).filter(t => run.includes(t.trial))
  settleTrials(usd, rows.reduce((s, t) => s + (Number(t.cost_usd) || 0), 0))
  const got = new Set(rows.map(t => t.trial))
  const missing = run.filter(k => !got.has(k)).map(k => ({ trial: k, status: 'harness_error', error: 'missing from harness result' }))
  return rows.concat(missing).map(t => ({
    ...t,
    config: cell.config,
    ticket: cell.ticket,
    cell: cell.id,
    key: `${cell.id}#${t.trial}`,
    dir: `${dir}/${t.trial}`,
    topup: isTopup,
  }))
}

// ---------- Code grader and leak scan ----------
async function gradeRows(rows, phaseName) {
  const okRows = rows.filter(r => r.status === 'ok')
  const batches = chunk(okRows, GRADE_BATCH)
  const outs = await parallel(batches.map((b, i) => async () => {
    const what = `${phaseName} grade batch ${i + 1}/${batches.length}`
    if (!reserveAgent(EST_GRADE, what)) return []
    try {
      const out = await agent(gradePrompt(b), { label: what, phase: phaseName === 'Top-up' ? 'Top-up' : 'Grade', schema: GRADE_SCHEMA, model: 'opus' })
      return out.results ?? []
    } catch (e) {
      log(`${what} failed: ${String(e)}`)
      return []
    } finally {
      settle(EST_GRADE, EST_GRADE)
    }
  }))
  const byKey = {}
  for (const g of outs.flat()) byKey[g.key] = g
  return rows.map(r => {
    if (r.status !== 'ok') return { ...r, graded: false, valid: false, voided: false }
    const g = byKey[r.key]
    if (!g) return { ...r, graded: false, valid: false, voided: false, grade_missing: true }
    const graded = Boolean(g.grader_ran)
    const tampered = graded && (g.file_category !== (r.label?.category ?? null) || g.file_priority !== (r.label?.priority ?? null))
    const voided = Boolean(g.peeked) || tampered
    return {
      ...r,
      graded,
      grader_error: g.grader_error || null,
      category_ok: graded ? Boolean(g.category_ok) : null,
      priority_ok: graded ? Boolean(g.priority_ok) : null,
      pass: graded ? Boolean(g.category_ok && g.priority_ok) : null,
      peeked: Boolean(g.peeked),
      peek_evidence: g.peek_evidence || '',
      tampered,
      voided,
      valid: graded && !voided,
    }
  })
}

function checkHalts(rs) {
  const peeks = rs.filter(r => r.peeked)
  if (peeks.length) addHalt(`leaked answer key: ${peeks.length} trial(s) read graders, answers, or predictions (${peeks.slice(0, 5).map(r => r.key).join(', ')})`)
  const broken = rs.filter(r => r.status === 'ok' && r.graded === false && !r.grade_missing)
  if (broken.length) addHalt(`grader error on ${broken.length} trial(s): ${broken[0].grader_error}`)
  const tampered = rs.filter(r => r.tampered)
  if (tampered.length) log(`VOID ${tampered.length} trial(s): reported label differs from result.json (${tampered.slice(0, 5).map(r => r.key).join(', ')})`)
  const missing = rs.filter(r => r.grade_missing)
  if (missing.length) log(`UNGRADED ${missing.length} trial(s): grade batch returned no result`)
}

// ---------- Run ----------
log(`Round ${ROUND}: ${cells.length} cells x ${TRIALS} trials, configs ${CONFIGS.join(', ')}, spend cap $${SPEND_CAP}, agent cap ${MAX_AGENTS}${DRY ? ', DRY RUN' : ''}`)
log(`Trial budget $${TRIAL_BUDGET.toFixed(2)} after holding back $${HOLD_BACK.toFixed(2)} for grading, judging, and synthesis`)
if (TRIAL_BUDGET < cells.length * TRIALS * EST_TRIAL) {
  log(`WARNING: planned trials need $${(cells.length * TRIALS * EST_TRIAL).toFixed(2)} at the estimate. Some trials will be skipped.`)
}
log('The judge is Opus, which is the same model family as the agent under test. No judge from another family is available, so tone scores may share its blind spots.')

phase('Trials')
const planNums = Array.from({ length: TRIALS }, (_, i) => i + 1)
const trialRows = (await parallel(cells.map(cell => () => runCell(cell, planNums, 'Trials')))).flat()
log(`Trials returned ${trialRows.length} rows. ok=${trialRows.filter(r => r.status === 'ok').length}, harness_error=${trialRows.filter(r => r.status === 'harness_error').length}, rate_limited=${trialRows.filter(r => r.status === 'rate_limited').length}. Spent $${ledger.spent.toFixed(2)}`)

phase('Grade')
let rows = await gradeRows(trialRows, 'Grade')
checkHalts(rows)
if (budgetHit) addHalt(`spend cap $${SPEND_CAP} reached during planned trials`)

phase('Top-up')
let topupCells = []
if (halt.length === 0) {
  const byCell = groupBy(rows.filter(r => r.valid), r => r.cell)
  topupCells = cells
    .map(c => {
      const rs = byCell[c.id] ?? []
      const p = rs.filter(r => r.pass).length
      return { cell: c, n: rs.length, passRate: rs.length ? p / rs.length : 0, split: p > 0 && p < rs.length }
    })
    .filter(x => x.split)
    .sort((a, b) => Math.abs(a.passRate - 0.5) - Math.abs(b.passRate - 0.5))
    .slice(0, DRY ? 1 : TOPUP_CELL_CAP)
    .map(x => x.cell)
  log(`Top-up: ${topupCells.length} split cell(s), ${TOPUP_PER_CELL} extra trials each, cell cap ${TOPUP_CELL_CAP}`)
  const extraNums = Array.from({ length: TOPUP_PER_CELL }, (_, i) => TRIALS + i + 1)
  const extra = (await parallel(topupCells.map(cell => () => runCell(cell, extraNums, 'Top-up')))).flat()
  const extraGraded = await gradeRows(extra, 'Top-up')
  checkHalts(extraGraded)
  rows = rows.concat(extraGraded)
} else {
  log(`Top-up skipped: ${halt.join('; ')}`)
}

phase('Judge')
if (halt.length === 0) {
  const rand = rng(SEED)
  const byTicket = groupBy(rows.filter(r => r.valid && r.reply), r => r.ticket)
  const jobs = Object.keys(byTicket).sort().map(ticket => ({
    ticket,
    items: shuffle(byTicket[ticket], rand).map((r, i) => ({ rid: `R${i + 1}`, key: r.key, reply: r.reply })),
  }))
  const judged = await parallel(jobs.map(job => async () => {
    const what = `judge ${job.ticket}`
    if (!reserveAgent(EST_JUDGE, what)) return []
    try {
      const out = await agent(judgePrompt(job.ticket, job.items), { label: what, phase: 'Judge', schema: JUDGE_SCHEMA, model: 'opus' })
      const byRid = {}
      for (const it of job.items) byRid[it.rid] = it.key
      return (out.scores ?? []).filter(s => byRid[s.rid]).map(s => ({ key: byRid[s.rid], ...s }))
    } catch (e) {
      log(`${what} failed: ${String(e)}`)
      return []
    } finally {
      settle(EST_JUDGE, EST_JUDGE)
    }
  }))
  const toneByKey = {}
  for (const s of judged.flat()) toneByKey[s.key] = s
  rows = rows.map(r => {
    const s = toneByKey[r.key]
    return s ? { ...r, tone_score: s.tone_score, tone_pass: s.tone_pass, tone_reason: s.reason } : { ...r, tone_score: null, tone_pass: null }
  })
  const judgedCount = rows.filter(r => r.tone_score !== null).length
  log(`Judge scored ${judgedCount} of ${rows.filter(r => r.valid).length} valid trials`)
} else {
  log(`Judge skipped: ${halt.join('; ')}`)
}

phase('Synthesis')
function summarize(config) {
  const planned = rows.filter(r => r.config === config && !r.topup)
  const valid = planned.filter(r => r.valid)
  const toned = valid.filter(r => r.tone_score !== null && r.tone_score !== undefined)
  return {
    config,
    planned_trials: cells.filter(c => c.config === config).length * TRIALS,
    completed: valid.length,
    voided: planned.filter(r => r.voided).length,
    harness_errors: planned.filter(r => r.status !== 'ok').length,
    ungraded: planned.filter(r => r.status === 'ok' && !r.graded).length,
    skipped: ledger.skipped.filter(s => s.what.startsWith(`${config}:`)).length,
    category_acc: rate(valid, r => r.category_ok),
    priority_acc: rate(valid, r => r.priority_ok),
    both_acc: rate(valid, r => r.pass),
    tone_mean: mean(toned.map(r => r.tone_score)),
    tone_pass_rate: rate(toned, r => r.tone_pass),
    runtime_s_mean: mean(valid.map(r => r.runtime_s)),
    tool_calls_mean: mean(valid.map(r => r.tool_calls)),
    tool_errors_mean: mean(valid.map(r => r.tool_errors)),
    tokens_mean: mean(valid.map(r => r.input_tokens + r.output_tokens)),
    cost_usd_total: planned.reduce((s, r) => s + (Number(r.cost_usd) || 0), 0),
  }
}
const summaries = CONFIGS.map(summarize)
for (const s of summaries) {
  log(`${s.config}: completed ${s.completed}/${s.planned_trials}, category ${s.category_acc}, priority ${s.priority_acc}, both ${s.both_acc}, tone mean ${s.tone_mean}, tone pass ${s.tone_pass_rate}`)
}
const ceiling = summaries.length > 0 && summaries.every(s => s.both_acc === 1)
if (ceiling) log('CEILING: every config scored 1.0 on both labels. Check once for a leak or a grader bug before close-out.')

const topupStats = topupCells.map(c => {
  const rs = rows.filter(r => r.cell === c.id && r.valid)
  return { cell: c.id, trials: rs.length, pass_rate: rate(rs, r => r.pass) }
})

const failed = rows
  .filter(r => r.valid && (!r.pass || r.tone_pass === false))
  .slice(0, FA_MAX_ROWS)
  .map(r => ({
    key: r.key,
    config: r.config,
    ticket: r.ticket,
    got: r.label,
    category_ok: r.category_ok,
    priority_ok: r.priority_ok,
    tone_score: r.tone_score ?? null,
    tone_reason: r.tone_reason ?? null,
    dir: r.dir,
    reply_start: (r.reply || '').slice(0, 300),
  }))

let failureAnalysis = null
if (failed.length && reserveAgent(EST_JUDGE, 'failure analysis')) {
  try {
    failureAnalysis = await agent([
      'You do failure analysis for the triage agent eval. The failed trials are below as JSON.',
      failed.length === FA_MAX_ROWS ? `The list stops at ${FA_MAX_ROWS} rows. Say so in your output if a type looks undercounted.` : '',
      'Read spe/failures.md. Reuse an existing F-number when a failure matches an existing type. Name a new type only when none fits.',
      'You may read spe/evals/tasks/answers.json, the ticket files, and the run directories listed. Do not read spe/predictions/ or spe/plans/. Do not say whether predictions were right. The close-out does that.',
      'Group the failures into types. For each type give the name, kind, existing F-number or null, the count per config, up to 3 example keys, how to spot it, and a proposed fix.',
      'List any failure that looks like a grader or answer-key error rather than an agent error, with the key and the reason.',
      '',
      JSON.stringify(failed),
    ].join('\n'), { label: 'failure analysis', phase: 'Synthesis', schema: FA_SCHEMA, model: 'opus' })
  } catch (e) {
    log(`Failure analysis failed: ${String(e)}`)
  } finally {
    settle(EST_JUDGE, EST_JUDGE)
  }
}

const criticInput = {
  round: ROUND,
  dry_run: DRY,
  configs: CONFIGS,
  cells: cells.length,
  trials_per_cell: TRIALS,
  halt,
  budget_hit: budgetHit,
  ceiling,
  ledger: { spent_usd: ledger.spent, cap_usd: SPEND_CAP, agents: ledger.agents, agent_cap: MAX_AGENTS, skipped: ledger.skipped },
  summaries,
  topup: topupStats,
  voided: rows.filter(r => r.voided).map(r => ({ key: r.key, peeked: r.peeked, tampered: r.tampered, evidence: r.peek_evidence })),
  harness_errors: rows.filter(r => r.status !== 'ok').map(r => ({ key: r.key, status: r.status, error: r.error ?? null })),
  ungraded: rows.filter(r => r.status === 'ok' && !r.graded).map(r => r.key),
  judge_missing: rows.filter(r => r.valid && (r.tone_score === null || r.tone_score === undefined)).map(r => r.key),
  failure_types: failureAnalysis ? failureAnalysis.types.map(t => t.name) : null,
}

let critic = null
if (reserveAgent(EST_JUDGE, 'completeness critic')) {
  try {
    critic = await agent([
      'You are the completeness critic for the triage agent eval. You check whether the run is complete enough to score. You do not score the agent.',
      'Check each of these against the JSON below.',
      '1. Every planned cell has its full trial count completed, or each missing trial has a logged reason.',
      '2. Voided trials, harness errors, and ungraded trials are counted and explained. A harness error or rate limit is not a model failure.',
      '3. Every valid trial has a tone score, or the gap is explained.',
      '4. Spend and agent count stayed under their caps, and every skip is logged.',
      '5. A ceiling, a leak, or a grader error is flagged plainly.',
      '6. The headline numbers use only the planned trials. Top-up trials appear only in the top-up table.',
      'Return verdict complete or gaps, and list each issue with a severity and the evidence.',
      '',
      JSON.stringify(criticInput),
    ].join('\n'), { label: 'completeness critic', phase: 'Synthesis', schema: CRITIC_SCHEMA, model: 'opus' })
  } catch (e) {
    log(`Completeness critic failed: ${String(e)}`)
  } finally {
    settle(EST_JUDGE, EST_JUDGE)
  }
}

log(`Done. Spent $${ledger.spent.toFixed(2)} of $${SPEND_CAP}. Agents ${ledger.agents} of ${MAX_AGENTS}. Skipped ${ledger.skipped.length}. Halt: ${halt.length ? halt.join('; ') : 'none'}. Critic: ${critic ? critic.verdict : 'not run'}`)

return {
  round: ROUND,
  dry_run: DRY,
  halt,
  budget_hit: budgetHit,
  ceiling,
  ledger: { spent_usd: ledger.spent, cap_usd: SPEND_CAP, agents: ledger.agents, agent_cap: MAX_AGENTS, skipped: ledger.skipped },
  summaries,
  topup: topupStats,
  failure_analysis: failureAnalysis,
  critic,
  rows: rows.map(r => ({ ...r, reply: (r.reply || '').slice(0, 300) })),
}
